L000046	\title{\textbf{Transit-time oscillations in nanoscale vacuum diode with a pure resistive load}
L000047	}
L000048	
L000049	
L000050	\author{Bjart\thór Steinn Alexandersson}
L000051	\author{Kristinn Torfason}
L000052	\author{Andrei Manolescu}
